{
  "lines": [
    {
      "id": "reflection.checkin",
      "tiers": [
        {
          "id": "reflection.checkin:t1",
          "title": "Дневник навострил страницы",
          "phrase": "Ты сохранил отметки самочувствия или дискомфорта в 3 разных дня. Дневник слушает — оценок не ставит.",
          "imagePrompt": "A small anthropomorphic accordion notebook with two stubby feet cups one page beside its cover like a listening ear. A short pencil rests across its open pages, ready to record whatever comes next.",
          "fishMarkup": "[warm]Ты сохранил отметки самочувствия или дискомфорта в 3 разных дня. Дневник слушает — <soft>оценок не ставит.</soft>",
          "audioText": "Ты сохранил отметки самочувствия или дискомфорта в 3 разных дня. Дневник слушает — оценок не ставит."
        },
        {
          "id": "reflection.checkin:t2",
          "title": "Записано как есть",
          "phrase": "В твоей истории уже 10 дней с отметками самочувствия или дискомфорта. Ты записываешь, как есть, — у дневника нет любимых ответов.",
          "imagePrompt": "An anthropomorphic accordion notebook with two stubby feet pushes a handcart carrying its own expanding pages. A short pencil serves as the cart handle, while one loose page curls upward like an attentive ear.",
          "fishMarkup": "[confident]В твоей истории уже <emphasis>10 дней</emphasis> с отметками самочувствия или дискомфорта. Ты записываешь, как есть, — у дневника нет любимых ответов.",
          "audioText": "В твоей истории уже 10 дней с отметками самочувствия или дискомфорта. Ты записываешь, как есть, — у дневника нет любимых ответов."
        },
        {
          "id": "reflection.checkin:t3",
          "title": "Архив без экзаменов",
          "phrase": "У тебя уже 30 дней с отметками самочувствия или дискомфорта. Ты собрал целый архив ощущений — без экзамена на бодрость.",
          "imagePrompt": "An anthropomorphic accordion notebook with two stubby feet drives a tiny forklift, lifting the towering folds of its own paper tail. A short pencil rides the raised forks like a librarian reporting for an absurdly oversized shift.",
          "fishMarkup": "[triumphant]У тебя уже <emphasis>30 дней</emphasis> с отметками самочувствия или дискомфорта. Ты собрал целый архив ощущений — <slow>без экзамена на бодрость.</slow>",
          "audioText": "У тебя уже 30 дней с отметками самочувствия или дискомфорта. Ты собрал целый архив ощущений — без экзамена на бодрость."
        }
      ]
    },
    {
      "id": "reflection.months",
      "tiers": [
        {
          "id": "reflection.months:t1",
          "title": "Улитка листает месяцы",
          "phrase": "Ты оставил отметки ощущений в 2 разных календарных месяцах. У дневника появилась история с продолжением, а не норматив по скорости.",
          "imagePrompt": "A curious snail carries a shell formed from two overlapping blank calendar leaves. It gently lifts the front leaf with a feeler, revealing the second beneath, while its eyestalks peer around the newly opened edge.",
          "fishMarkup": "[warm]Ты оставил отметки ощущений в 2 разных календарных месяцах. У дневника появилась <soft>история с продолжением</soft>, а не норматив по скорости.",
          "audioText": "Ты оставил отметки ощущений в 2 разных календарных месяцах. У дневника появилась история с продолжением, а не норматив по скорости."
        },
        {
          "id": "reflection.months:t2",
          "title": "Календарь на борту",
          "phrase": "Ты отмечал ощущения в 4 разных календарных месяцах. Твоя история обзавелась главами — календарь уже устраивается поудобнее.",
          "imagePrompt": "A snail carries four blank calendar leaves arranged into a roomy shell. One leaf folds outward into a little reading ledge; the snail leans back beneath it, using a curled leaf corner as an unexpectedly practical headrest.",
          "fishMarkup": "[confident]Ты отмечал ощущения в <emphasis>4 разных календарных месяцах.</emphasis> Твоя история обзавелась главами — календарь уже устраивается поудобнее.",
          "audioText": "Ты отмечал ощущения в 4 разных календарных месяцах. Твоя история обзавелась главами — календарь уже устраивается поудобнее."
        },
        {
          "id": "reflection.months:t3",
          "title": "Летопись на ракушке",
          "phrase": "Ты оставил отметки ощущений в 8 разных календарных месяцах. Это уже летопись — календарь просит у тебя автограф.",
          "imagePrompt": "A snail's shell unfolds into an enormous fan of eight blank calendar leaves, dwarfing its delighted owner. Beneath the sweeping pages, the snail solemnly presents a comically tiny pencil and a blank autograph card toward the viewer.",
          "fishMarkup": "[triumphant]Ты оставил отметки ощущений в <emphasis>8 разных календарных месяцах.</emphasis> Это уже летопись — <slow>календарь просит у тебя автограф.</slow>",
          "audioText": "Ты оставил отметки ощущений в 8 разных календарных месяцах. Это уже летопись — календарь просит у тебя автограф."
        }
      ]
    }
  ]
}
